    "无 broker 回复，故 source_use=[]；无 development_step.gap，不能复制学习请求字段。"
  ],
  "next_actions": [
    "取得原研究可读方法与图注后，核实 dphi 单位、DOP 定义、采样和误差来源。",
    "补入独立偏振光学教材或综述，逐字保存来源与支持引文；当前不可用外部检索补齐。",
    "分别保留 spread 与 mean_phase 分支，并记录新材料如何改变理解。"
  ],
  "materials": [
    {
      "id": "M1",
      "observation": "spread 扫描 102 行；预览 DOP 从约 93.14 降至约 31.00；统计 dphi 范围 0–约 0.505。",
      "conditions": "Fig2a；DOP 约 0–100 标度。单位待核实，无独立重复及原始不确定度。",
      "expectation": "未知。",
      "expectation_basis": "缺少独立理论或综述。",
      "existing_explanations": "相位展宽导致贡献相消仅为条件性解释，未核实。",
      "unknowns": "dphi 单位、DOP 定义、测量汇总、扫描顺序、误差、控制变量及完整曲线。",
      "source_ids": [
        "D1"
      ]
    },
    {
      "id": "M2",
      "observation": "mean_phase 扫描 200 行，覆盖 0 至 2π；预览 DOP 约 0.73–0.84，方向分量随预览点变化。",
      "conditions": "Fig2b；DOP 约 0–1 标度，不与 Fig2a 原始值合并。",
      "expectation": "未知。可提出平均相位是否主要改变方向而非偏振度的问题。",
      "expectation_basis": "缺少独立领域基础资料。",
      "existing_explanations": "未提供论文解释。",
      "unknowns": "完整响应、周期处理、S 分量约定、DOP 关系及误差。",
      "source_ids": [
        "D1"
      ]
    }
  ],
  "sources": [
